    isbn: "",
    desc: "《AI未来已来》是李开复写给CEO、组织和每个普通人的AI时代行动指南。\n作者以40年AI研究、创业和投资经验为基础，判断AI不再只是工具，而是正在重塑企业成本结构、决策系统、组织形态与个人价值的新生产力。\n全书从AI为何比工业革命影响更深、智能体如何走向企业一线讲起，指出多数AI转型失败的根源：只买模型和工具，却没有重构业务、数据、责任与组织。书中提出企业AI决策中枢、“老板AI”、DRI责任制、一人公司等关键概念，并进一步讨论当执行被机器接管后，人的品味、远见、信念和勇气为何变得更加稀缺。\n它既是企业管理者的AI转型手册，也是一封写给普通人的提醒：未来已来，真正重要的不是会不会使用AI，而是能否借AI重新定义自己的位置。",
