    desc: "全书包含两个部分。《克林索尔的最后夏天》是黑塞创作于1919年的中篇小说。彼时一战刚刚结束，世界尚未从混乱中恢复，千万士兵、战俘和民众，从多年僵化统一的顺服中，回归既向往又恐惧的自由。有些年轻人在童年时被战争拖走，现在“回归”了，却必须面对一个完全陌生的现实世界。而对于黑塞这样的“老人”，那些曾被高度认同的世界观已成了可笑荒唐的明日黄花。一切都变得可疑，令人不安惶恐。在这样一个夏天，一个告别的夏天，充满力量与光芒、诱惑与魅力，弥漫南方阳光与葡萄酒香气的日子，画家克林索尔化身李太白，与他的好友杜甫、路易、亚美尼亚占星师，一同漫游，饮酒，辩论。最终在夏末，用尽生命所有的燃料，完成了最终的画作。第二部分《漫游》是黑塞创作的散文和诗歌集。",
