    desc: "“浪漫”与“地理学”看似是一对矛盾的词。地理学脚踏实地，充满常识，亦是生存所必需。在过去，每个人都要懂得去哪里寻找食物、水源和栖息地；而如今，所有人都必须细心经营地球家园，使之更宜安居。当今的地理学著作缺乏戏剧性，地图、数据、描述和分析比比皆是，却没有豪侠之举，没有孜孜以求的精神。然而，在不远的历史中，地理学的确曾有魔力，并被认为是浪漫的。那是一个英勇探索的时代。探险家深入海洋、山岳、森林、洞穴、沙漠和极地冰原，检验着自己身体和精神的忍耐力……作者指出，若是将精神视为人类存在的核心，或许人类需要将整个宇宙当作游乐场：超越中庸之道，信奉诸如光与暗、高与低、头脑与肌肉等两极化价值，皈依一些并不满足生存需要，却迎合热烈的浪漫渴望的地理环境。全书以灵动的笔调，从哲学、心理学、人类学的角度讲述人性与大地的互动，发掘地理学的诗性潜力。",
