    tag3: ["自我认知"],
    isbn: "9787521744354",
    desc: "双相情感障碍，俗称躁郁症，是指患者既有躁狂或轻躁狂发作，又有抑郁发作的一类心境障碍，仿佛一个身体里住进了两个灵魂。作为一种常见的心境障碍，它因凡·高、贝多芬等患有此病的天才而为人所知，但事实是大众存在大量忽视或者被误诊的情况，患者甚至需要数十年才能得到正确的诊断。本书作者自青少年时发病，历经13年确诊，又用10年控制病情逐渐好转，通过自己二十多年与双相情感障碍共存的经历，道出最真实的病患的生活、工作、亲密关系、社会交往。在这本书中，你会了解并收获：什么是双相情感障碍；躁狂或者抑郁发生时，对患者而言到底意味着什么？会发生怎样的故事和意外？除了痛苦和煎熬，如何好好挖掘与激发“天才”的一面？面对污名化，如何正视和应对？为自己发声，也是治愈自己的方式；给家人、朋友和护理工作者的实用建议。",
