    tag3: ["非虚构写作"],
    isbn: "9787222232068",
    desc: "借着二十多桩遭遇，作者从内行视角呈现了精神医学行业，更隐隐勾勒出自己三十多年的人生。\n重症精神病患者的苦楚，外人往往难以理解：温和的园丁因精神病史而遭社会排斥，终日请脑内的声音和自己作伴；妄想的儿子不知自己发病时要杀了妈妈；男子先跳桥后趴轨四肢尽断却依然活着；对分裂症管用的药让猛男胸部淌奶……另一方面，精神医学研究并不成熟，对患者的帮助依然有限甚至有时适得其反；精神科在医院各科室中又是资源少风险高，科内医生往往有更高的精神问题风险乃至患病率，连某位主任也不得不因重度焦虑而休长假——留下在岗者继续7*24运转。此时，遑论救人，精神科医生又如何自救？\n作者自己，则是家族有酗酒、暴力、失智、精神病等多种精神、神经障碍史，于他常是阴暗的记忆，也阻挠着他建立、维护亲密关系。抱着帮助家人和自己的心愿选择了精神科的他，只是越发无助地发现众生皆苦，万事皆难。\n尽管如此，作者依然选择在这个行业中坚持和奋进，凭着信念、人性和苦中作乐讲地狱笑话的喜剧精神，“救一只海星是一只”。",
