    isbn: "",
    desc: "《今古奇观》是一部白话短篇小说的选集，明抱瓮老人编。主要选自冯梦龙的“三言”和凌濛初的“二拍”。书中的作品多角度、全方位地反映了当时市民阶层的生活面貌思想感情。它既表现了资本主义萌芽时期的新思想，又留存着消极和庸俗的旧意识。明朝中叶以来，通俗文学界掀起了编总集的高潮。文言白话小说领域都出现了许多小说总集。随着明末经济的发展，商业的繁荣，文化权力下移，通俗文学家、书商们开始注重平民大众的文化需求。文人们收集整理民间文学作品、说话人的底本和单篇话本小说，编为话本小说集。冯梦龙的“三言”和凌蒙初的“二拍”便是这些总集的代表之作。而《今古奇观》就是以“三言”、“二拍”为基础的优秀选本。这部白话短篇小说集在社会上非常流行，传播很广，其影响甚至超过了原本，对中国白话小说作出了贡献。《今古奇观》选本与原本“三言”、“二拍”之间有着密切的联系。",
