    desc: "2010年末，李娟跟随哈萨克牧民居麻一家深入北疆阿勒泰地区沙漠深处的冬牧场，度过了一整个冬天。在漫长的寒冷世界里，李娟详实地记录下这块古老、贫瘠又广阔的土地上的所见所闻：牧民们迁徙、放牧、背雪、绣花毡、整地窝子清理畜圈，隆重豪华地串门拜访……艰辛繁重的劳动是日常也是阔大寂寞生活的乐趣与尊严。这是哈萨克族逐水草而居的游牧生活中最动荡艰难的一个季节，随着时光流转与外部世界物质的丰富，这种生活方式行将逐渐消失。所幸李娟的文字真实还原了这个场景——牧人们的冬天和牲畜们的冬天，“羊的一生是牧人的一年”。",
