    isbn: "9787508692890",
    desc: "这本书涵盖世界上二十余个主要的考古胜地，以及重要的考古发现，我们将看到埃及法老的黄金面具，希腊帕提侬神庙里的大理石雕像，墨西哥丛林中的祭献品……这些文物将尽可能客观地告诉我们，我们的祖先过着怎样的生活、创造过怎样的文明，其中的一些文明又为何走向毁灭。这也是一群“寻宝者”——考古学家——的传奇故事。1872年，谢里曼为寻找特洛伊，在土丘上挖开伤口一般的大沟；20世纪60年代，以色列人亚丁带领考古队攀上马萨达陡峭的山顶，用筛子筛了约3.8万立方米的泥土来寻找文物；2010年，这本书的作者克莱因与“太空考古学家”萨拉·帕卡克凝视卫星图像，在田野中发现公元2世纪罗马“铁甲团”的兵营遗址。书中还展示了不断进化的考古技术，比如空中勘察、激光雷达、碳-14测年法，它们让更多遗址被发现，也让文物说出更多故事。作者还站在考古学家的角度回答了普通人的常见疑惑：你怎么知道在哪里挖掘？你怎么知道某件东西年代有多久？你找到的东西归你吗？就这样，考古的故事带领我们向人类历史的上游跋涉，并为我们带来关于未来的启示。",
