    desc: "作者在《自控力：和压力做朋友》中提供这样一个概念：压力就是你在乎的东西发生危险时引起的反应。这个定义足够大，可以涵盖交通阻塞引起的沮丧和失去事物的痛楚。它包括感到压力时的想法、情绪、生理反应，以及你选择怎样应对压力情境。这个定义也强调了有关压力的一个重要真相：压力和意义无法分割。对不在乎的事情，你不会感到压力；不经受压力，你也无法开创有意义的生活。“在这本书中，你将学习到的策略来自成百上千项的调查、与我交谈过的数十位科学工作者的智慧，你会了解他们最吸引人的研究。”但最重要的，这是一本帮你与压力共存的实用指南。",
