    isbn: "9787522901213",
    desc: "后疫情时代，抑郁、焦虑正在日益成为越来越多人的“新常态”。根据zui新调查，我国有近1亿人罹患抑郁障碍，其中百分之29.8的患者合并患有焦虑障碍，然而，与这种普遍性相对的是，得到充分治疗的抑郁患者不足百分之1。精神卫生与心理健康问题已成为重大公共危机，其治疗进展关乎我们每个人的生活与未来。\n在《抑郁、焦虑和药物的那些事》中，有11年临床治疗经验的知名心理学畅销书作家劳伦·斯莱特以学者、医者、患者三重身份，带领读者一起探索精神医学领域中那些改变人类世界的药物和前沿技术。斯莱特通过引人入胜的叙事方式，以划时代的药物为切入点，呈现了近100年来人们与“心魔”的抗争历程——从药物的诞生过程与坎坷的上市之路，到药品监管机构、制药公司与医学人士的各种考量，再到患者，包括作者本人35年的服药治疗经历。从这本书中，读者不仅能看到患者、医生、科学家与疾病之间的顽强斗争，感受到人类的智慧与人性的坚强，还能从患者报告以及作者亲身的体验中认识到，现有的常用药物对他们来说有多有效，又有哪些需要特别注意的副作用与鲜为外人所知的长期影响。\n如果你对重要的医学进展与深刻的人性议题感兴趣，抑或正在直接或间接受“心魔”所扰，这本书会让你获得你所需的信息与更广阔的视角，丰富你的医学与人文素养，甚至给你勇气与希望，帮助你做出有利于提升人生质量的决定。",
