    isbn: "9787530212196",
    desc: "中国千古第一奇相大传，全票获得第六届茅盾文学奖、首届姚雪垠长篇历史小说奖、中宣部五个一工程奖，被誉为中国新时期长篇小说的里程碑！已被改编成电视剧《万历首辅张居正》，由唐国强、梅婷、冯远征、智一桐、巫刚等一众老戏骨主演。张居正是一位个性不凡的改革家，是彪炳史册的传奇人物。他登上首辅之位后，理政十年：整顿吏治，刷新颓风；整治教育，延揽济世之才；革新税赋，梳理财政。拯朱明王朝将倾之厦，使万历时期成为大明王朝*为富庶的时代。 在风云际会之中，张居正思想深邃，刚毅深沉，多谋善断，声势显赫，无与伦比。然而，他一朝大权在握，却又独断专行，偏信阿谀奉承，引得附势者趋之若骛。权势欲促使他步入人生高峰，也引发身后祸起萧墙。隆葬归天之际，即是遭人非议之时，结果家产尽抄，爵封皆夺，祸连八旬老母，罪及子孙。作为一名政治家，张居正是中国历史上卓有成效的人；可是作为一个人，他却是一个失败者。“生前显耀，死后悲凉”是对他一生*好的概括。他生前死后毁誉之悬殊，除个人原因之外，也可见政治险恶、世态炎凉。而且，张居正的命运也客观揭示了悲剧产生的历史背景与人物的性格缺陷，为今天的读者反思提供了形象的文学读本。",
