    tag3: ["先秦史", "秦汉史", "魏晋南北朝史", "隋唐史", "宋辽金史", "元史", "明史", "清史"],
    isbn: "9787542643216",
    desc: "《叫魂》所讲述的是一个关于“盛世妖术”的故事。在中国的千年帝制时代，乾隆皇帝可谓是前没有古人 后没有来者的一人。他建立并巩固起来的大清帝国达到了权力与威望的巅峰。然而整个大清的政治与社会生活却被一股名为“叫魂”的妖术之天错地暗。在1768年由春天到秋天的那几个月里，这股妖风竟然冲击了半个中国，百性为之惶恐，官员为之奔命，连乾隆也为之寝食难安。作者细致入微的描写令人颤栗，他生动地再现了各省的恐慌是如何演变成一场全国性的除妖运动。\n本书也表现出了一种更为宏大的学术视野，在构建以“叫魂”案为中心的“大叙事”的过程中，在方法论的层次上将社会史、文化史、政治史、经济史、区域分析、官僚科层制度分析以及心理分析等研究方法结合在一起。本书可作为学生必读参考书。",
