    tag3: ["趣味科普"],
    isbn: "9787518098507",
    desc: "你有多久没有仰望星空了？你知道时间从何而来？历法如何制定？日月星辰在其中，又到底扮演了怎样的角色？\r\n《七堂极简天文历法课》是一本天文历法入门读物。作者齐锐结合日常生活中遇到的有趣问题，以天文历法为主旨，全面阐述了我们日用而不知的天文历法。主要内容包括：时间的称谓，历法的制定，突出天文学“观象授时”的意义；以日常使用的公历为例，讲述一年365.25天的历法周期律，着重介绍了被列入“人类非物质文化遗产代表作名录”的“二十四节气”；从月相变化周期出发，介绍了农历历法的一年十二个月和十三个月。书中还重点揭开了古老历法十月历的神秘面纱，并指出它是我国传统文化中阴阳五行的天文起源。此外，还为读者梳理了各种传统纪元历法，以引导大家更好地走进灿烂辉煌的天文历法世界。\r\n本书注重中国传统文化的传承，追溯了古代文化常识的来龙去脉，旨在给读者一个完整的知识体系。同时，全书语言简洁，条理分明，没有烦琐的推算，只有平易的讲述，即使没有科学背景的人，也能轻松读懂。",
