    tag3: ["人生哲学"],
    isbn: "9787308086141",
    desc: "《维特根斯坦传:天才之为责任》是哲学家维特根斯坦的生平传记。与其他相关传记不同的是，《维特根斯坦传:天才之为责任》较多的涉及到维特根斯坦的生活和个性方面，因而不只是维特根斯坦的研究者，普通对哲学感兴趣的读者也能从中获得丰富、深入的阅读体验。媒体推荐蒙克的《维特根斯坦传》丰富、深入、好读，公认为维特根斯坦的最佳传记，在我看，实是思想家传记中少见的佳作，不仅向我们展现了这位伟大思想家的深刻的灵魂生活，而且有助于我们理解他的哲学思想。译者王宇光中英文俱佳，不辜负原著。——陈嘉映蒙克的这本传记运笔深透，对普通读者也丰盛可口……一个美妙生命的一幅美妙肖像。——《卫报》",
