    isbn: "9787542677815",
    desc: "重点大学寄托了万千家庭改变命运的梦想，如今一系列专项招生计划也为更多学子打开了机会之门。然而，金榜题名之后，学子是否如想象那般顺遂？不同社会经济背景的学生在毕业出路和职业前景上的差距是如何拉开的？通过对位于京沪的两所重点高校毕业班学生的深度访谈，本书揭示了大学生在上大学过程中遭遇的一种隐性的挑战：是否洞察大学场域的“游戏规则”，掌握其中“默认”为常规的一系列认知和实践模式。本书指出，家庭背景优势不仅带来了雄厚的物质支持，更意味一整套关于“上大学”的文化技艺的传承，这使得出身优渥的大学生得以在白热化的出路竞争中抢占先机，而家境平平者却更容易与机会失之交臂。本书也关注了意义感在出路获得中的重要作用，指出了在当前的制度背景下，内化主流价值信念、扩充“文化工具箱”有助于帮助大学生走出生涯目标迷失的困境，从而更高效地利用大学资源，获得生涯出彩机会。",
