    isbn: "9787547010792",
    desc: "《真实的幸福》内容简介：过去的50年，心理学只关心一件事——心理疾病，而且做得不错，因为现在我们可以测量抑郁症、精神分裂症、酗酒等过去认为是很模糊的概念，并能做出相当精准的描绘。目前我们已经知道这些问题是怎么发展出来的，包括它们的遗传因子、生物化学性以及心理成因，最重要的是我们知道该怎么去治疗这些疾病。根据我最近的统计，在几十种心理疾病中，已经有14种可以用药物及心理治疗方法来进行有效医治（两种可以完全治愈）。但是这种进步的代价很高：为了要摆脱问题状态，我们会变得更痛苦，甚至还不如以前。人不只是要改正错误或缺点，还希望找出自己的优势和生活的意义。人都不愿意糊里糊涂过一生。你可能会像我一样，午夜梦回，躺在床上想自己的生活是如何越变越幸福，而不是一天天减少痛苦。假如你真像我一样，你可能会对心理学有点失望。但是现在，它终于走到了解积极情绪，建构优势和美德（strength and virtue），为亚里士多德所谓的“美好人生”提供指引的时候了。",
