    desc: "为什么我们活得那么累？为什么我们越来越茫然？为什么我们甚至开始不知道“我是谁”？我们被指责内卷，又被指责躺平；我们被贩卖孤独，又被推销爱情；我们被推向对立，又被斥为无情……于是有人问，这代年轻人怎么了？可是，我们也想问，我们应该怎样“正确”地生活、自由地生活？年轻是属于阅读、游历和爱情的。复旦大学中文系教授、宝藏老师梁永安在《梁永安：阅读、游历和爱情》中如是说——我对年轻人有两个建议：一，要保持对世界的好奇心；二，要走出自我舒适区，在新的东西里寻找人生。现近代以来，爱情最大的要素就是女性的变化，而很多男性没有跟上女性的思想转变。现在很多年轻人的自由时间被剥夺了，整天“996”，两性之间自然没有很宽松的体验。复旦大学教授梁永安老师从爱情、工作、自我、修养、孤独、社交、人格、艺术、女性文化等具体十五个主题切入当下青年群体的时代症候，期望与青年人一起突破对问题的单一认知，找到新的理解方式，体会到生活的无限可能与多元价值。跟随梁永安，在不确定的时代，做确定的自己。",
