    desc: "“穿过县境上长长的隧道，便是雪国。夜空下，大地赫然一片莹白……” \r\n东京舞蹈艺术家岛村在三次去往多雪的北国山村，与当地一名叫驹子的艺伎由邂逅而情爱。而他再次出发，却对玻璃窗对面萍水相逢的少女叶子，流露出一番倾慕之情。虚无思想甚重的岛村，认为人生的一切营求和努力，都归“徒劳”，对驹子的身世自感爱莫能助，决心分手；驹子虽然追求真挚的爱情，也终归“徒劳”而化为泡影；而叶子在意中人病逝后，与岛村约定好，前往东京，没想到，最后却迎来了一场大火……\r\n《雪国》为川端康成倾注心力最多的一部作品，也是其诺贝尔文学奖的获奖作品之一。该书由“国宝级”翻译家高慧勤翻译，完整呈现日式物哀之美的原貌，意境悠远，动人心脾。",
