    isbn: "9787559474407",
    desc: "听骆老师讲古诗词，总是鼻子酸酸的、心里暖暖的！\n复旦特受欢迎的教授！超火爆的诗词课！\n《古诗词课》根据骆玉明老师多年来备受欢迎的《古典诗词导读》一课整理而来，在他的讲述中读者和诗词作者之间没有了时空上的距离，站在同一种处境上品味人生，读者在读懂诗词的同时感受自己的生命历程，治愈生活的焦虑。语言或俏皮幽默，或尖锐深刻，丝毫没有“说教感”，只有深切的关怀，让读者产生深深的共鸣。\n从《诗经》楚辞讲到唐诗宋词，这21节治愈人心的诗词课，用极具代表性的经典诗词还原古诗词中的人生境遇，深刻展现亘古不变的人性。\n翻开本书，在骆老师的带领下轻松走进诗词深处，获得发自内心的感动！\n《咏怀•第七十一》：焦虑不是消极，而是对生命的敏感\n生命就是一个充满焦虑的走向死亡的过程。这是阮籍诗歌的一种表达，也是叔本华哲学的一个表达。人有时候会凝视着生命的这种焦虑灰暗和无望，不能把它理解为一个纯粹的消极现象，因为从中我们看到的是一种对生命的敏感。 \n《春江花月夜》：正因为我到这里，世界才这样美好\n江上的月亮在等待谁呢？每一个人都是被这个世界所等待的，世界之所以有意义，是因为你用你的方法去认识了世界，每个人都用自己的方法赋予世界以意义。当我们看到江上的月亮的时候，我们就可以这样去想，我正是那个月亮所等待的人。\n《锦瑟》：往事如梦，但往事里的痛苦是真实的\n虽然人生如梦，但是人生中的痛苦是确切的，是深刻的，是不可遗忘的。你现在不要追究李商隐了，你追究你自己吧。你的那些往事，它们现在缥缈像一个幻影。可是那些往事里面留下的痛苦和悲哀，它不是刻在梦里面的，它是刻在你心里面的。",
