    desc: "与他人建立深度关系的能力对我们的生活和工作至关重要。当身处一段深度关系中时，我们会感到自己被理解和支持。然而，有时我们会发现自己很难与他人建立深度关系，或者无法应对与他人更亲密时不可避免会出现的挑战。\n事实上，所有的关系各不相同，但多数都会按照相似的模式发展。建立和维持深度关系的过程是可以描述、学习和应用的。\n本书内容源自斯坦福商学院50余年经典课程“人际互动”，两位作者将人际心理学的重要核心知识点应用在5种典型的人物关系——父女、夫妻、闺蜜、兄弟、同事中，探讨了关系由浅入深的发展过程，指明了深度关系的6个特征，让抽象的关系变化看得见，帮助读者与家人、朋友和同事建立充分信任、彼此成就的深度关系。",
