    desc: "在探险者的心中，西藏总有一份难以言喻的魔力。\n张书清，一位对西藏有着近乎疯狂的热爱与向往的旅者，1998年，他踏上了前往西藏的征程。三个月的时间，他驾车穿越墨脱，探访藏北，领略山南，直至抵达阿里。这一路上，他遇到了无数令人动容的故事：新四军老战士为了建成背崩希望小学，不顾年岁翻越大雪山；全国最年轻的墨脱县公安局局长给予了他帮助；中央民族学院的高才生为了在墨脱办学，从北京调往此处……这一路上的种种意外：在藏北迷路、在珠峰下堵车、掉进帕羊河、在阿里高原上车出故障并遇到狼，都在沿途部队和当地百姓的帮助下，化险为夷。\n关于这段传奇经历，如今都被浓缩在了《独行西藏》一书中，等待你来探索。",
