    desc: "人类总是问题多多：关于宇宙，关于地球，关于时间和空间，也关于我们自己。\n我敢保证，以下问题里你至少曾经想过一个：\n（当你犯了错误时）能让时间倒流吗？\n（当你看了科幻电影时）外星人到底在哪里？\n（当你不想上班/上学时）能不能有另一个我代替？\n（当你不得不出远门时）为什么不能瞬间传送？\n（当你怀疑人生时）我们生活在模拟世界中吗？\n（当你担心世界末日时）会有小行星撞击地球吗，以及我们能移民到火星吗？……\n问题总是问不完，但感谢各位科学家的努力，我们人类其实已经知道很多了！\n包括但不限于以上的热门宇宙问题，你都能在这本书中找到答案，那种列出各种可能性的、脑洞大开的、充满搞笑漫画的、由物理学教授回答的答案。你也能在这些问题和答案中发现一些看似不可能的可能性和看似不合理的合理性，而它们都只是宇宙的基本规律而已。\n如果我们的宇宙是一种产品，那这本书就是产品说明书上的“热门问题与解答清单”，适合每一个正在体验该产品的人类。",
