    desc: "《我是个年轻人，我得了躁郁症》是一本带有自传性质的心理自助类图书。\r\n23岁、研究生毕业的年轻人阿杰正要展开新的人生，却在此时确诊了躁郁症，跌入了无边无际的黑暗，像被困住了。\r\n作者以躁郁症亲历者视角真实记录一场绝望与希望交织的生命之旅。他经历了困惑、怨恨，克服了如“木柴在火堆里烧得噼里啪啦”的痛苦后，终于走出黑暗，迎来清晨，并鼓励人们，躁郁症康复后，人还是那个人，日子还是那些日子，但生命开始有了坐标轴，我们拥有了托起自己的底气。\r\n全书分为“确诊以后的日子”“凭什么要好起来？”“开始治疗了……”“让头浮出水面”“ 康复的那一刻”五个章节，作为一个“过来人”，作者用直白平实的语言科普了在患病的每个阶段会遇到的困惑，同时提供了行之有效的方法，诚恳、细腻地描述了自己的切身感受，告诉我们，哪怕身处无边无际的黑暗，哪怕被消沉悲伤的情绪困住了，但也请你务必一而再，再而三，三而不竭，千次万次，毫不犹豫地救自己于人间水火。因为黑暗中的路无论有多远，都会有结束的那一刻，第二天的清晨也都会如约来临，而你也知道的，天亮之后，会很好看。",
