    desc: "黑白动画短片《她和她的猫》是以《秒速五厘米》等众多动画而名声大振的日本新锐动画导演新海诚“幻之出道作品”，制作于1999年初夏至初冬期间，发表于2000年。本片中，新海诚独自完成了除音乐和女主角声优以外的所有工作，以一只猫的视角，讲述了“他”与女主人在同一屋檐下度过的略带感伤的淡然日子。小说版《她和她的猫》是部小中篇，由《语言的海洋》《缘分的花朵》《假寐与天空》《世界的体温》等四个章节组成，围绕着养猫的几个女主人公不同的人生，描述了与动画版不同视点的别有新意的温馨故事，本书从猫的视角看待人的生活：上班，回家，失恋……猫眼中看到的女孩被世界拒之门外，却依然倔强地生活，她依旧向前走着，勇敢、坚强。世界以痛吻她，她却回报以歌。通过猫眼表现了生活在都市的年轻人的生存状态以及面对爱情、面对亲人、面对朋友、面对人生选择的种种真实心态。“我……或许还有她，都爱着这个世界呢。”故事中弥漫的淡淡忧伤和现今都市80后90后在大城市打拼、生活的一代人的心绪有共通之处，但不服输的正能量足以振奋心灵。",
