    tags: ["情绪与自我成长"],
    cat: "心理与成长",
    tag3: ["自我认知"],
    isbn: "9787521763157",
    desc: "如果你人生中有未完成的事件——来不及告别的人，得不到的回应，未被满足的需求，内心没有解决的冲突——试试在房间中放两把椅子，你坐其中一把，另一把留给未完成事件中的人（或者是你的一部分自我）。想象那个人坐在空椅子上，把你的感受、情绪和想法都告诉他。然后，你再坐在他的椅子上，想象你现在变成了他，用你想象他会对你说的话，来回应你刚才坐的那把椅子上的人（也就是你自己）。 童年时的我们为了保护自己，发展出了相应的适应能力和防御机制，比如乖巧、懂事、警觉、讨好。然而，当我们长大成人后，儿童式的生存机制不再适用于成年人的生活，甚至会带来创伤和阻碍，留下一桩桩“未完成的事件”。 在这本温暖人心的书中，心理治疗师菲利帕·佩里用温柔又犀利的回答，帮助读者看见自己，觉察自己，给未完成的事件逐一画上句号。 感谢童年时代拼力保护我们的自己，现在，让我们用成年的力量，再重新养育一次童年的自己。",
