    desc: "1971年，受“依附理论”激发，乌拉圭记者、作家兼诗人爱德华多·加莱亚诺出版了这部震撼世界的《拉丁美洲被切开的血管》，试图解剖拉美的病体，探讨大陆的前途。他用难以辩驳的丰富资料，以澎湃有力的悲情笔法，铺陈出这片大陆自哥伦布开启航海新纪元之后的崎岖命运，写下一页页拉美受难史：金银、可可、棉花、橡胶、咖啡、水果、石油、铁、镍、锰、铜、锡……这些“血管”贯穿了整个拉美大陆，延伸到开阔的尽头，在那里它们流入欧洲和美国的宝库。曾经的殖民主义野蛮掠夺这片土地；而自由贸易、经济援助、合资企业、国际组织等现代文明体制同样以不文明的手段参与古老的掠夺战。拉丁美洲是一个血管被切开的地区，是拉丁美洲不发达的历史构成了世界资本主义发展的历史。本书试图揭开拉丁美洲孤独百年的真相，也让我们聆听失败者的声音：那些追求拉美独立富强的英雄和他们失败的革命。这是整个拉丁美洲悲剧的缩影。与书中所揭示的历史被官方掩盖和篡改一样，本书在出版之后不久即遭到拉美右翼政府的禁令，然而它却以几十种语言的译本走遍世界，被一代人长久地当作叛逆拉丁美洲的象征。它的论断带着时代的烙印，它的命运却已经融入历史。",
