    desc: "一个穆斯林家族，六十年间的兴衰，三代人命运的沉浮，两个发生在不同时代、有着不同的内容却又交错扭结的爱情悲剧。这部五十余万字的长篇，以独特的视角、真挚的情感、丰厚的容量、深刻的内涵、冷峻的文笔，宏观地回顾了中国穆斯林漫长而艰难的足迹，揭示了他们在华夏文化与伊斯兰文化的撞击和融合中的心路历程，以及在政治、宗教的氛围中对人生真谛的困惑和追求，着力塑造了梁亦清、韩子奇、梁君璧、梁冰玉、韩新月、楚雁潮等一系列人物群像，血肉丰满，栩栩如生。\n本书一共有十五章，分为两种结构，两条故事线。第一个结构以“月X”为标题，主要讲述本是流浪的清真弟子韩子奇因打破手艺人梁亦清玉器而留下学手艺，拜梁亦清为师傅，帮助其完成郑和下西洋作品，因梁家突发意外，娶梁师傅大女儿梁君璧为妻，重振奇珍斋。以及讲述了韩子奇“传奇”的一生，讲述其与奇珍斋梁家两个女儿的故事。第二个结构以“玉X”为标题，主要讲授韩子奇女儿韩新月逐渐发现家中秘密，并在北京大学读书与班主任楚雁潮的爱情。今昔对比，相得益彰。",
