    isbn: "9787541165320",
    desc: "本书由八部中篇和短篇小说构成。水与火，柔软与尖锐，春天与冬天，植物与铁器，韩江在这些冲突中洞悉瞬间的感觉和印象，用美妙而生动的语言刻画命运的表情，在刺探人与人之间关系的阴暗面时，闪烁着耀眼的光芒。短篇集关注“底层”人群，每个主人公都像在“没有希望的世界里像孤儿一样”流浪。他们从偏僻小镇的旅馆房间、考试院走廊尽头的房间、黑暗的地下室或多户型住宅和高层公寓的走廊尽头走出来，经过黑暗的楼梯和没有路灯的胡同，走进纷繁的令人疲倦的城市大街之中。然而即使他们离开许许多多疲惫的人们和不幸的都市，来到偏僻的海边或边缘港口城市生活，最终还是要回归都市，这就是他们的宿命。他们处在都市喧闹、污染和复杂的人际关系中，却没有能够包容和安抚他们的乐园或是母亲。乐园和母亲只存在于梦中或是死亡的那一边。他们所在的世界是父亲的世界，是邪恶和冰冷的世界。那里是现实的世界，充满了蛇、数字13和4，还有冰冰冷冷的铁制品。而韩江小说中的人物将要在那里重生。",
