    isbn: "9787220124846",
    desc: "【人民日报社主办，国民级历史读物《国家人文历史杂志》爆款文精华结集】以时间为脉络，以“变化”为核心，精选制度、经济、军事、战略、朝堂5大主题、53个有戏又有料的话题，由点着面地纵向梳理了古代中国多个领域的承袭与变革。\n秦国星耀智囊团为何多是商鞅、张仪等外籍人士？汉武帝如何赚钱又烧钱？隋炀帝南巡开凿了大运河，西巡时又干了什么？李渊何以凭借3万兵马7年定天下？战术天才李存勖吃了哪些战略短板的亏？王安石如何成为靖康之变的背锅侠？胡惟庸为何必须死？崇祯是如何远程“帮倒忙”的？袁世凯为何策划了清末“PS门”事件？……历史就是一出你方唱罢我方登场的戏剧，这些熟悉的名字背后，不仅有跌宕起伏的故事，也浓缩了每个时代承袭、变革和发展的偶然性与必然性。本书是《国家人文历史》杂志公众号的精华结集，以时间为脉络，以“变化”为核心，精选制度、经济、军事、战略、朝堂5大主题、53个有戏又有料的话题，由点着面地纵向梳理了古代中国多个领域的承袭与变革，以动态的思维挖掘其背后的逻辑与本质，不仅还原了一个个鲜活多元的大时代，道出成败兴衰之理，更以诙谐的语言、独特的视角、严谨的考证，勾勒了今天中国的疆域版图、文化思想、经济格局、风俗人情和法度制度等多个领域的历史脉络。细节决定成败，格局决定结局。翻开本书，读懂古代中国的承袭与变革，就能读懂中国几千年的风云流转，更能读懂中国何以传承至今，历久弥新。",
