    isbn: "9787532773206",
    desc: "《博尔赫斯全集第一辑(套装共16册)》包括《恶棍列传》《小径分岔的花园》《杜撰集》《阿莱夫》《布罗迪报告》《沙之书》《埃瓦里斯托·卡列戈》《讨论集》《永恒史》《探讨别集》《诗艺》《序言集以及序言之序言》《博尔赫斯，口述》《七夜》《但丁九篇》《私人藏书：序言集》共十六册。博尔赫斯引领了二十世纪拉丁美洲文学潮，是西班牙语、拉丁美洲文学脉络中里程碑式的人物，“为一代西班牙语美洲小说家的脱颖而出铺平了道路”（诺贝尔文学奖得主、南非作家库切语），《百年孤独》的作者加西亚·马尔克斯说：“我在布宜诺斯艾利斯买的唯 一的东西就是《博尔赫斯全集》。我把这套书放在手提箱里，随身带着，打算每天取出来阅读。”其影响力更超出拉丁美洲、欧洲，成为二十世纪享有世界声誉的文学大师。\n本次版本是弥补市场近十年空白的独 家授权版本，权威翻译，经修订完善；并且消除成套全集的沉重感，首次以作家原作独立版本的单行本形式推出，让读者细致感受博尔赫斯的世界。",
