    isbn: "",
    desc: "魏晋风骨，化尽沉香。\r\n　　王谢世家，雅道相传。\r\n　　南方有佳人，名曰孟姜。\r\n　　逸少之幺女，子敬之妹。\r\n　　性本淑成，柔仪嘉门。\r\n　　————————————————\r\n　　魏晋，战火纷飞民生凋敝的时代，诗酒风流雅道相传的时代。\r\n　　王孟姜，书圣王羲之之女。史书上，她高雅、神秘，一笔带过。\r\n　　这个女子在这个时代，曾演绎过怎样的悲欢离合，曾见过怎样的风霜雨雪。\r\n　　孟姜晚年，暮春初夏，闲坐会稽郡庭院中读书，少年时代饱蘸鲜血与热情的笔墨依旧能够让她想起那个少年。他的诗，他的剑，他年轻、近乎明艳的面孔。\r\n　　抑或山阴道上桂花初绽的时节，笃笃轻拍在心上的木屐声。\r\n　　还是另一个孩子稚嫩的声音，他说，不见长安。\r\n　　你们还记得吗？\r\n　　曾经的梦想，王师北定。\r\n　　家国天下。",
