    desc: "被霍金、阿西莫夫盛赞的硬科幻高峰之作，影史经典《超时空接触》原著。影响人类世界观的天文学家、天体物理学家、雨果奖、普利策奖得主卡尔·萨根所写，既是科幻小说也是科普著作，基于其亲自参与的SETI（地外文明探测计划）项目经验撰写，呈现科学研究级别的硬核细节，影响一代人的科学观。以科学研究级的技术细节与隽永诗意，呈现人类对地外文明的恢弘想象。女科学家艾莉·艾罗维幼年丧父，凭借自己的聪敏坚毅在男性主导的射电天文学界闯出一席之地。她在系统地探测地外无线电信息时突然从织女星方向收到具有严格数学意义的信息。经过艰难破译，艾莉发现那是一种神秘交通工具的制造图纸。经历了一番科学家与政客的激烈交锋之后，消息被公之于众，全球都极度亢奋地投入到交通器的建造中。同时，与先进文明的接触带来了“神迹”的联想，民众的宗教狂热也被激发，社会上出现了各种冲突和对抗。由美国、苏联和中国等国的科学家组成的五人小组，在20世纪的最后一个下午作为人类代表乘坐交通器飞向织女星。在见证了一系列宇宙奇观后，在宇宙中一个中转站上降落。五名成员在这里分别经历了属于个人和民族的奇幻体验。小说真实地描写了这次接收消息、制作机器、穿梭黑洞飞抵银河的冒险探访的全部过程，探索宗教与科学的关系，对人性、科学精神、地外文明都进行了深刻的思辨与探索。",
