    desc: "漫画科普开创者二混子新作！全网粉丝700万！用特别有趣的方式，讲清楚特别艰深的经济学原理。亚当·斯密“看不见的手”、特沃斯基和卡尼曼“损失规避”、庞氏骗局、托奥斯基“价格锚点”、理查德·塞勒心理账户…… 打破经济学在你心目中高高在上的印象，让你在哈哈大笑中学到实用、简单、接地气的经济学知识！翻开本书，看作者如何用艰深的经济学原理抖包袱。在大多数读者的心目中，经济学都是专业、晦涩的代名词，但陈磊（笔名：二混子）领衔的半小时漫画团队，却通过手绘漫画和段子，深入浅出地将经济学与我们在现实生活中安身立命的问题结合了起来。养老金为什么入不敷出？国家为什么要放开二胎政策？我们缴的五险一金有什么用？买房前需要注意些什么？没有枯燥乏味的数字堆砌，没有生涩难懂的专业术语，只用有趣的段子和一看就懂的漫画解答这些生活常识问题，为你理清它们背后那些让人蒙圈的经济学原理：人口与经济的相互作用、借贷关系、货币的起源、消费者心理……打破经济学在你心目中高高在上的印象，让你在哈哈大笑中学到实用、简单、接地气的经济学知识！",
