    tag3: ["大众文化"],
    isbn: "9787521747614",
    desc: "了解过去的中国社会，对我们今天的普通人来说，重要吗？ 当然重要。 我们今天的文化、传统、习俗、审美等诸多方面，仍然深受过去长期形成的社会行为和文化传统影响。了解过去，我们才能更自在地活好当下。 而通常，我们了解的历史，多是王侯将相、知识精英、英雄豪杰，少了普通人的生活。本书则聚焦微历史，以微观和宏观相结合的方法，从一个个普通人和家庭的故事，逐步延伸至中国社会的方方面面，从而展现人口的变迁、衣食住行、农村和城市的形成、秘密社会、风俗习惯、文人与教育、宗教信仰、法律与社会、宗族与家庭等等，让大家看到更细节的中国。 本书分为上、下两卷。 上卷“人、日常和文化”聚焦中国人的日常生活与文化。人们为什么会“以貌取人”，服饰是如何反映阶层和社会变迁的？厨房里的必需品与人们的环境和生活习惯有什么样的关系？古代的轿子、车、船有什么独特发展历程？从集市到城镇，这种流通与集散的网络是如何形成的？真实的“勾栏”“瓦舍”是我们以为的勾栏、瓦舍吗？古人为什么喜欢翻老黄历？“十里不同俗”，传统社区的人们是靠什么凝聚起来的？古代真的无“礼”寸步难行吗？ 下卷“家、群体和法律”，则讲述家族、群体和法律。家族是中国传统社会的基石，宗族力量不容小觑，那宗族是一个使钱生钱的公司吗？在传统的儒家社会，法律的制定是从哪里出发的？传统社会的那些酷刑与刑具，是怎么发明出来的？除了庙堂，江湖上的三教九流、黑帮会社靠什么来管理？中国传统社会有“小升初、中考和高考”吗？“万般皆下品，唯有读书高”，文人们真的都“书画琴棋诗酒花”，诗意地栖居？ 看历史就像看电影，我们会看到全景、中景，但更真实的情景可能来自近景与细节。我们只有把历史放在显微镜下，倾听普通人的声音，才能看到更鲜活、更有血有肉的历史，感受中国社会的烟火与温度。",
