    tag3: ["趣味科普"],
    isbn: "9787521731583",
    desc: "为什么曾经浪漫的感情也会变淡？为什么成功人士通常不会觉得自己很成功？为什么几乎所有的节食计划后来功亏一篑？为什么聪明的人也经常会做出糟糕透顶的决定？这取决于大脑中的一种单分子结构——多巴胺。这种化学物质控制着你的欲望、想象、冲动、创造力，出乎意料地影响着我们生活的方方面面。我们的身体受到“向上”和“向下”两类物质的控制。“向下”指的是控制当下的神经递质，它们决定了我们当前的感受；“向上”则是指多巴胺，它们决定了我们的长远规划、愿景、未来期望。正因如此，多巴胺并不像很多人以为的，是一种快乐分子。它其实是一种欲望分子，在我们已经获得很多的同时，让我们有更高的期许、更大的目标。多巴胺让我们把眼光放得更长远，追求更高的目标，但也同时让人欲望无止境、不知道满足。它既能让你体会成功的喜悦，也让成功变得平淡无奇；它让你投入一段感情，但也能让当初的深情被岁月磨平；它能让你获得超高的智商，但也让你与疯狂一步之遥……了解这种物质是如何影响我们的情绪、决策和生活的，能够帮助我们充分发挥大脑的潜在功能，提高办事效率，在工作和生活中获得更好的表现。",
