    isbn: "9787508669052",
    desc: "在《第五项修炼》中， 美国麻省理工学院彼得•圣吉明确提出了“学习型组织”的管理理念，以及如何通过五项修炼来打造有学习力的学习型组织，强调从事一项修炼就意味着成为一个终身学习者。在这五项修炼中，重要的一项修炼是系统思考，即第五项修炼。系统思考是观察整体的修炼，可以帮助我们深刻理解个人向内观、向外看的全新方法。一个组织能够拥有长期竞争力的关键在于，有比竞争对手更快、更好的学习力和修炼方法。系统思考还需要开发共同愿景、心智模式、团队学习和自我超越的修炼，才能发挥出潜力。 彼得•圣吉是少有的跨界人才，能够整合系统思考模式和跨界思维，不断丰富全球公司的发展案例和战略总结，西方管理学理论和东方哲学思想，同时长期关注中国企业的发展，强调企业在创新和试错中不断自我成长和进化的修炼。 我们习以为常的思向和秩序是不断变化的，但系统思考可以提升我们对整体的认知，看清局部和整体的关系，找到整个系统的关键影响力。从现实到未来，从实际到未来地践行从个人学习到组织学习的“知行合一”。",
