    desc: "自1946年出版以来，《菊与刀》一直被视为世界理解日本的起点。它不仅塑造了西方对日本的基本认知，也深刻影响了日本人理解自身的方式。书名中的“菊”是日本皇室家徽，“刀”是武士文化的象征。“菊与刀”的组合，成为对日本民族性格经典的象征和诠释。\n“日本人既好战又温和，既崇尚军国主义又崇尚唯美主义，既傲慢自大又彬彬有礼，既古板僵化又有很强的适应能力， 既顺服屈从又憎恨被人摆布， 既忠心耿耿又奸诈狡猾， 既勇敢无畏又胆小怯懦， 既保守又乐于接受新鲜事物，而且全都达到了极端的程度。”（见第2页）\n读客三个圈专家伴读版，邀请复旦大学徐英瑾教授万字导读+13篇全书伴读，逐章纠正原书偏见，让你彻底看懂日本！",
