    desc: "30多年前，“旅行者1号”探测器在结束太阳系探测使命时回眸一望，拍摄下了我们的地球家园。在这幅发人深省的照片里，地球就像一粒飘浮在宇宙中的尘埃，享誉全球的美国天文学家和科普大师卡尔•萨根别有深意地称之为“暗淡蓝点”。我们都生活在这个小小的世界上，或许有一天将离开这里去往其他星球。\n本书是萨根在60岁那年出版的科普名著，宛如一部纵贯往昔、今日与未来的史诗，于宏伟缜密间编织着大量扣人心弦的精彩故事。他首先回顾了历史上有关人类在宇宙中的地位的种种观念，接着根据20世纪下半叶太空探测的成就对太阳系做了全方位的考察，然后评估了将人送入太空的种种理由，最后对人类未来的太空家园进行了长远展望。阅读这本书就像在与萨根进行亲切的交谈，他将引导我们放下人类的自大和傲慢，然后鼓足勇气去探索更辽阔的星际宇宙。这不仅是我们长久以来的愿望，更是人类生存与文明进步的必然。\n“地球是人类的摇篮，但人类不可能永远被束缚在摇篮里。”谨以此纪念卡尔•萨根诞辰90周年。",
