    desc: "在三百万年的人类进化史中，\n谁能率先掌握先进技术，\n就能取得阶段性领先，甚至灭掉其他竞争者。\n因此，从地缘角度写一部人类史，\n不仅是复盘人类的进化历程，\n展示各有所长的诸多文明，\n比较东西方的成败优劣，\n更是要寻找隐藏于地理与时间背后的规则，\n以及那些关键的技术节点，\n帮助大家重新认识自己，看清未来世界的走向。\n地图上有人类的过去、现在和未来，每一段故事都会以不同形式反复上演。看懂地图，才能看懂波澜激荡的历史；看清地缘，才能看清未来世界新走向。  \n翻开这本书，你将看到：\n◎人类是如何脱离动物范畴，变身为万物之灵的？\n◎为何人类文明发源于热带，兴盛于温带？\n◎为什么尼罗河阻碍了埃及向非洲腹地传播文明，反而促使全新类型的海洋文明出现？\n◎是什么让人类可以突破血缘纽带，实现社群扩张，团结更多人？这带来的不仅是内、外信仰的统一，更是一套成熟的社会运行机制。\n◎为何别的民族会因外族入侵而四分五裂，中国即使被打到被迫南迁，也能重归一统？\n◎中国人的“家国”式集体主义是怎么形成的？这种自上而下的资源分配，为什么在中国以外地区并无可能实现？\n◎神能够成为什么样的神，并不是由自己决定的，神祇存在的终极价值是为设计它们的人类服务。\n◎为什么科学与工业革命出现在西方？以中国为代表的东方在人类现在正经历的信息革命中又有什么独特优势？",
