    isbn: "9787516832684",
    desc: "词从小道、艳科，难登大雅之堂，到上升为“一代之文学”，中间经历了怎样的历史变迁？是哪些人使宋词完成了蜕变？是哪些事在宋词中留下深刻印痕？而宋词又是怎样与一个王朝的兴衰相始终？这背后，大有故事可讲。\n可惜的是，许多研究宋词的书籍，更喜欢沿着文学鉴赏的老路，去告诉读者这首词好在哪儿，而往往忽略了作品诞生的时代信息——这背后可能是一场惊心动魄的战争，可能是一次你死我活的政治斗争，抑或可能是一次宾主尽欢的宴饮，又抑或是一曲哀伤痛悟的临终寄语。\n一个作品，诞生的历史信息，有时更能引起我们的兴趣。这也是本书花了这么多笔墨去追述宋词流传过程的原因，每一次整理保存都携带着那个时代的信息，从而超越了词作本身的意义与内涵。有鉴于此，本书或许是独特的：不是从文学角度去解析宋词的美与痛，而是尝试着从历史角度去走近宋词的时代氛围，去读取深藏其中的兴衰起落，生老病死，辉煌、深沉、热闹与沉默。",
