    desc: "写给成年人的恋爱课，适用于确定关系后的情感经营阶段。专门针对容易恋爱脑，一谈恋爱就患得患失，吵架争执就焦虑想分手的恋爱症候群。\n爱情本是一个美好的礼物，但当下越来越多人，因为怕相处、磨合的麻烦而“懒得”谈恋爱。殊不知，恋爱是一场成年人的必修课，两个人是可以通过学习和练习来获得优秀的成长学分的！帮助过数千人成功脱单的心理咨询师，擅长爱情心理学和关系经营学，在书中帮你深度分析两性交往中的内在成长动机，陪你练习，并给出实操的方案，解决每一个关系难点。\n看到对方身上有你无法忍受的缺点该怎么办？\n吵架时觉得对方触及了你的原则线怎么办？\n伴侣不懂提供情绪价值怎么办？\n觉得恋爱后对方的态度变冷淡了怎么办？\n……\n所有相处的问题，都是人性成长的内在动机问题，这本书会帮你由心出发，了解对方，解决问题，处理关系，让彼此成长为最好的伴侣。",
