    isbn: "9787533965617",
    desc: "《柠檬》是日本知名作家梶井基次郎的短篇小说合集，收录其20篇短篇小说代表作，包括《柠檬》《樱花树下》《冬蝇》《雪后》等，原汁原味按照1931年日本武藏野书院发行的最初版本，呈现了梶井基次郎31年人间生活的遐思、情绪和感悟。\r\n生命灰白，但柠檬鲜活。一个摇摇欲坠的灵魂，数着日子过活，于是忧郁，失意，格格不入，逃离、孤独、病痛、毁灭交织，但生命之欣欣，总令人舍不得放弃，拯救人的最终都是微小的生活，所以才会因一颗柠檬、一个玻璃弹珠获得自顾自的快乐。\r\n梶井基次郎用文字来记录社会生活中微不足道的、看似无意义的、微妙的变化和意识现象，不以巧言来修饰而是忠实于自己内心的表达需求，用清冽的文字来表现现代生活中不幸的灵魂的真实样貌，因而被誉为“昭和的古典”，三岛由纪夫等作家都曾表明受其影响。",
