    tag3: ["教育学", "教育心理"],
    isbn: "9787515367088",
    desc: "本书以“人类是如何思考和学习的”为线索，按章节依次阐述了大脑关于学习的10项基本运作原理，回答了诸如为何我们无须费力就能记住热播剧剧情却记不住知识等普遍学习困惑，揭示了故事、情感、记忆、背景知识、练习在构建知识和创造持久学习经验中的重要性，据此给出教育工作者提高学生的学习能力及精进教学技艺的方法建议。 \n作者的多个观点会颠覆你的固有认知，你将会重新认识并思考以下主题：“事实性知识优先于技能知识”“反复练习是精通任何脑力工作的开始”“因材施教是否有科学性证据支持”“智能可通过持续努力而改变掌握10大认知原则，就能掌握有效学习的诀窍，不是你不喜欢学习，原来是大脑喜欢这样学！",
