    "desc": "威廉·H.怀特最有魅力的地方，是他真的去街上“看人”。他使用长期观察、录像和行为记录研究广场、人行道、街道、公园、座椅、阳光、树木等因素如何影响人的停留与交往。很多今天已经很熟悉的“人本公共空间”理念，在这里都能找到非常具体的观察基础。读它之后再坐在一个城市广场里，会很容易开始观察：人为什么偏偏坐这里，而不坐那里？"
