    "desc": "阿尔多·罗西的这本书是20世纪建筑与城市理论的重要文本。罗西反对把城市简单理解为一个可以随意规划的功能机器，强调城市中的建筑类型、纪念物、历史结构与“集体记忆”。在他的视角下，一座城之所以成为这座城，是因为时间不断在建筑和空间中留下痕迹。因此它理论密度较高，但对理解“城市为什么具有历史连续性”非常关键。"
