    "desc": "叶兆言把南京写成故事发生的空间本身。小说主要置于辛亥革命前后约二十年的时代变化中，通过普通人物、城市底层与时代激流之间的互动，呈现传统社会瓦解、现代城市形成时南京的复杂面貌。“仪凤门”既是一座真实城门，也像一道历史边界：城里城外、旧与新、个人与时代都在这里碰撞。"
