    "desc": "这是一部讨论“历史学究竟如何成为一门学问”的基础著作，不是简单罗列历史知识，而是从史学的对象、方法、材料、历史认识、史家主体性等问题切入。适合作为史学方法论的入口，尤其适合已经喜欢历史、但想从“看故事”进一步进入“怎样研究历史”的读者。",
